props.onDataChangeTransform:
(
  $productStrategyProcessId :=$parent.data.id;
  $selectedRows := data[selected];
  
/*if object for $productStrategyProcessId does not exists in the StateForm, append it*/  
  $processStepsMoves := $components.Screen.context.processStepsMoves[productStrategyProcessId=$productStrategyProcessId] or $isNil($productStrategyProcessId)?
                        $components.Screen.context.processStepsMoves:
                        $append($components.Screen.context.processStepsMoves, {"productStrategyProcessId":$productStrategyProcessId, "selectedRows":[]});

/*update the value with the selected rows
  $processStepsMoves ~> | $processStepsMoves[productStrategyProcessId=$productStrategyProcessId] | {"selectedRows": $selectedRows}|;*/
  $selectedRows
    ? $processStepsMoves ~> | $processStepsMoves[productStrategyProcessId=$productStrategyProcessId] | {"selectedRows": $selectedRows}|
    : $processStepsMoves ~> | $processStepsMoves[productStrategyProcessId=$productStrategyProcessId] | {"selectedRows": []}|;

/*set the field processStepsMoves in StateForm*/
  $components.Screen.fn.setContextValue("processStepsMoves", $processStepsMoves); 
  $components.MoveStepsTable.fn.selectRow(data[selected].id);
  $components.MoveStepsTable.fn.setSelectedRows(data[selected].id);
  $processStepsMoves

)

